use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        if ctx.question.len() > 512 {
            return ResponseResult::Error(LlmError {
                message: "question too long".to_string(),
            });
        }

        let system = "You are a customer support assistant. Use the knowledge base via the lookup tool when needed.";

        match tool_llm::generate(system, &ctx.question) {
            Reply::Text(text) => ResponseResult::Ok(AgentResponse { text }),
            Reply::Call(req) => {
                if req.tool != "lookup" {
                    return ResponseResult::Error(LlmError {
                        message: format!("unknown tool: {}", req.tool),
                    });
                }

                let results = kb_read::lookup(&req.query);
                let prompt = format!(
                    "Question: {}\nLookup results:\n{}",
                    ctx.question,
                    results.join("\n")
                );

                match tool_llm::generate(system, &prompt) {
                    Reply::Text(text) => ResponseResult::Ok(AgentResponse { text }),
                    Reply::Call(_) => ResponseResult::Error(LlmError {
                        message: "model requested a second tool call".to_string(),
                    }),
                }
            }
        }
    }
}

export!(Node);
